* glue.s - integration of the (relocated, patched) arcade program with the Neo Geo runtime.
*
*   game_main   : entered from USER (demo/title request): sets up the I/O shadow and jumps to the
*                 arcade reset entry 0x2400 (its SSP is relocated to ARC_WRAM+0x3F80 by the patcher).
*   frame_hook  : called from our VBlank handler after SYSTEM_IO: feeds the inputs, runs the arcade
*                 VBlank handler (0x2F8C) on the runtime stack, then syncs palette/tiles/sprites.
*   mcu_frame   : in mcu.s.
*   oracle stubs: generated by tools/mkrom.py into build/stubs.s.

        .include "neogeo.i"
        .include "ram.i"

        .text
        .global game_main, sound_init, frame_hook, trap1_handler

        .equ    ARC_RESET,      0x2400
        .equ    ARC_IRQ6,       0x2F8C
        .equ    ARC_WRAM_STACK, ARC_WRAM+0x3F80

* ---- arcade input word (700002/3), active low ----
        .equ    ARC_P1_UP,      0
        .equ    ARC_P1_DOWN,    1
        .equ    ARC_P1_RIGHT,   2
        .equ    ARC_P1_LEFT,    3
        .equ    ARC_P1_GEAR,    4
        .equ    ARC_P1_ACCEL,   5
        .equ    ARC_COIN1,      6
        .equ    ARC_COIN2,      7
        .equ    ARC_START1,     14
        .equ    ARC_START2,     15

sound_init:
        rts

game_main:
        bsr     io_init
        clr.b   rt_in_game
        clr.b   rt_gear
        clr.b   rt_coin_pulse
        clr.b   rt_start_pulse
        clr.b   rt_start_req
        bsr     selftest_decrypt
        jmp     ARC_RESET

* I/O shadow defaults: DSW = 0xFFDF (MAME defaults: joystick, 2 sticks, normal, demo sounds on, 1C/1C),
* inputs idle, SYSTEM idle, wheel idle.
io_init:
        move.w  #0xFFDF,IO_DSW
        move.w  #0xFFFF,IO_P1P2
        move.w  #0x00FF,IO_WHEEL
        move.w  #0xFFF3,IO_SYSTEM
        rts

* Build the arcade input word from the Neo Geo controls (BIOS_P1CURRENT: bit0 up,1 down,2 left,3 right,
* 4 A,5 B,6 C,7 D, active high after SYSTEM_IO).  A = accelerate, B = gear toggle, C = accelerate too.
io_update:
        move.w  #0xFFFF,d0
        move.b  BIOS_P1CURRENT,d1
        btst    #0,d1
        beq.s   1f
        bclr    #ARC_P1_UP,d0
1:      btst    #1,d1
        beq.s   2f
        bclr    #ARC_P1_DOWN,d0
2:      btst    #2,d1
        beq.s   3f
        bclr    #ARC_P1_LEFT,d0
3:      btst    #3,d1
        beq.s   4f
        bclr    #ARC_P1_RIGHT,d0
4:      move.b  d1,d2
        and.b   #0x50,d2                /* A or C */
        beq.s   5f
        bclr    #ARC_P1_ACCEL,d0
5:      /* gear toggle on B press (edge) */
        move.b  d1,d2
        and.b   #0x20,d2
        move.b  rt_prev_b,d3
        move.b  d2,rt_prev_b
        tst.b   d3
        bne.s   6f
        tst.b   d2
        beq.s   6f
        eori.b  #1,rt_gear
6:      tst.b   rt_gear
        beq.s   7f
        bclr    #ARC_P1_GEAR,d0
7:      /* start: raw button or synthetic pulse */
        move.b  BIOS_STATCURNT,d1
        btst    #0,d1
        beq.s   8f
        bclr    #ARC_START1,d0
8:      tst.b   rt_start_pulse
        beq.s   9f
        subq.b  #1,rt_start_pulse
        bclr    #ARC_START1,d0
9:      /* synthetic coin after PLAYER_START (BIOS validated the credit) */
        tst.b   rt_start_req
        beq.s   10f
        clr.b   rt_start_req
        move.b  #2,rt_coin_pulse
        move.b  #20,rt_start_pulse
10:     tst.b   rt_coin_pulse
        beq.s   11f
        subq.b  #1,rt_coin_pulse
        bclr    #ARC_COIN1,d0
        bset    #ARC_START1,d0          /* coin first, start a few frames later */
11:     move.w  d0,IO_P1P2
        rts

* frame_hook: runs inside our VBlank handler (all registers saved by the caller)
frame_hook:
        bsr     io_update
        /* run the arcade IRQ handler on the runtime stack with a fake exception frame */
        move.l  sp,rt_saved_sp
        lea     RT_STACK,sp
        pea     arc_irq_done
        move    sr,-(sp)
        jmp     ARC_IRQ6
arc_irq_done:
        bsr     palette_sync
        bsr     video_frame
        move.l  rt_saved_sp,sp
        rts

* TRAP #1: dispatch an arcade VRAM write (2/4-byte instruction replaced by the trap) to its stub.
* Stack on entry: SR.w, PC.l (PC = address after the trap opcode).
        .global trap1_handler
trap1_handler:
        movem.l d0-d1/a0-a1,-(sp)
        move.l  18(sp),a0               /* return PC */
        lea     trap_table,a1
1:      move.l  (a1),d0
        beq     trap_error_pc
        cmp.l   d0,a0
        beq     2f
        lea     12(a1),a1
        bra     1b
2:      move.l  8(a1),d0
        add.l   d0,18(sp)               /* skip the padding after the trap */
        move.l  4(a1),rt_trap_stub
        movem.l (sp)+,d0-d1/a0-a1
        pea     trap1_rte
        move.l  rt_trap_stub,-(sp)
        rts                             /* -> stub, which returns to trap1_rte */
trap1_rte:
        rte
trap_error_pc:
        movem.l (sp)+,d0-d1/a0-a1
        jmp     trap_error

* palette_sync: arcade palette RAM shadow (xBRG444, entries 0..1023) -> ARC_PAL (Neo Geo format) for
* the 16-colour palettes whose raw words changed since the last call.
palette_sync:
        lea     ARC_PALRAW,a0
        lea     ARC_PALLAST,a1
        lea     ARC_PAL,a2
        lea     rt_pal_dirty,a3
        lea     pal_table,a4
        moveq   #63,d7
ps_pal:
        movem.l (a0),d0-d3
        cmp.l   (a1),d0
        bne.s   ps_conv
        cmp.l   4(a1),d1
        bne.s   ps_conv
        cmp.l   8(a1),d2
        bne.s   ps_conv
        cmp.l   12(a1),d3
        bne.s   ps_conv
        movem.l 16(a0),d0-d3
        cmp.l   16(a1),d0
        bne.s   ps_conv
        cmp.l   20(a1),d1
        bne.s   ps_conv
        cmp.l   24(a1),d2
        bne.s   ps_conv
        cmp.l   28(a1),d3
        bne.s   ps_conv
        lea     32(a0),a0
        lea     32(a1),a1
        lea     32(a2),a2
        addq.l  #1,a3
        dbra    d7,ps_pal
        rts
ps_conv:
        moveq   #15,d6
1:      move.w  (a0)+,d0
        move.w  d0,(a1)+
        and.w   #0x0FFF,d0
        add.w   d0,d0
        move.w  (a4,d0.w),(a2)+
        dbra    d6,1b
        st      (a3)+
        st      rt_pal_any
        dbra    d7,ps_pal
        rts

* selftest_decrypt: decrypt a few known pairs into rt_test_out so the MAME harness can check decrypt_long
selftest_decrypt:
        lea     test_vals(pc),a0
        lea     rt_test_out,a1
        moveq   #5,d1
1:      move.l  (a0)+,d0
        jsr     decrypt_long
        move.l  d0,(a1)+
        dbra    d1,1b
        rts
test_vals:
        .long   0x4D0FF8A6, 0x40544454, 0x095DB400, 0x4054EBE5, 0x3A3F3D18, 0xC8411F0E
        .align  2
